def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_my, last_opp = history[-1]

    opp_d = sum(1 for _, o in history if o == 'D')
    opp_d_rate = opp_d / n

    if opp_d_rate > 0.8:
        return 'D'

    if last_my == 'D' and last_opp == 'C':
        return 'D'

    if last_my == 'C' and last_opp == 'D':
        if opp_d_rate > 0.5:
            return 'D'
        else:
            return 'C'

    if last_my == 'D' and last_opp == 'D':
        if opp_d_rate > 0.5:
            return 'D'
        else:
            return 'C'

    if last_my == 'C' and last_opp == 'C':
        consec_cc = 0
        for i in range(n - 1, -1, -1):
            if history[i][0] == 'C' and history[i][1] == 'C':
                consec_cc += 1
            else:
                break
        if consec_cc >= 10:
            return 'D'
        else:
            return 'C'

    return 'C'
